    h1 { font-size: var(--runs-type-h1-size); line-height: var(--runs-type-h1-line); font-weight: var(--runs-type-h1-weight); }
    h2 { font-size: var(--runs-type-h2-size); line-height: var(--runs-type-h2-line); font-weight: var(--runs-type-h2-weight); }
    p { font-size: var(--runs-type-body-size); line-height: var(--runs-type-body-line); font-weight: var(--runs-type-body-weight); }
    li { font-size: var(--runs-type-list-size); line-height: var(--runs-type-list-line); font-weight: var(--runs-type-list-weight); }
    .visual-gallery { width: 100%; max-width: 920px; margin: 16px 0; }
    .visual-figure { margin: 0 0 16px 0; }
    .image-zoom-trigger { display: block; width: 100%; padding: 0; overflow: hidden; border: 0; border-radius: 16px; background: transparent; cursor: zoom-in; }
    .visual-image { display: block; width: 100%; max-width: 920px; height: auto; object-fit: contain; }
    .visual-caption { margin-top: 8px; text-align: center; font-size: var(--runs-type-caption-size); line-height: var(--runs-type-caption-line); font-weight: var(--runs-type-caption-weight); }
    .visual-lightbox[hidden] { display: none; }
    .visual-lightbox { position: fixed; left: 0; top: 0; right: 0; bottom: 0; z-index: 9999; background: rgba(10, 18, 30, .88); }
    .visual-lightbox-dialog { position: relative; width: 100%; height: 100%; margin: 0; }
    .visual-lightbox-stage { position: absolute; left: 0; top: 0; right: 0; bottom: 0; display: flex; align-items: center; justify-content: center; overflow: hidden; touch-action: none; }
    .visual-lightbox-image { display: block; width: 92%; height: auto; max-height: 72%; object-fit: contain; transform-origin: center center; }
    /* 圆形 ×：脚本将其定位在图片底部与视口底部之间的纵向中点。 */
    .visual-lightbox-close { position: fixed; top: 82%; left: 50%; z-index: 2; width: 46px; height: 46px; margin: 0; padding: 0; border: 0; border-radius: 50%; color: #fff; background: rgba(102,100,111,.94); font-size: 31px; line-height: 43px; font-weight: 800; transform: translateX(-50%); }
  </style>
</head>
<body>
  <main class="summary-page">
    <div class="summary-scroll">
      <div class="top-safe-area" aria-hidden="true"></div>

      <section class="completion-card" aria-labelledby="completionTitle">
        <div class="trophy-wrap" aria-hidden="true">
          <img
            src="https://res.xrunda.com/xruns/static/image/course_summary_trophy.png"
            alt=""
          >
        </div>
        <h1 id="completionTitle">恭喜你完成本节课程！</h1>
      </section>

      <section class="summary-card" aria-label="本课小结">
        <h2 id="summaryTitle">五项信息组成完整的问题说明</h2>
        <section class="visual-gallery" id="visualGallery" data-visual-group-layout="vertical_stack" data-visual-placement-terminal="forbidden" aria-label="课程配图"></section>
        <div class="summary-content" id="summaryContent" data-summary-static="true"><p class="summary-paragraph">现在，把刚才的信息合在一起：</p><blockquote class="summary-quote">第一次参加社区桌游体验的人，不清楚不同游戏需要的人数和时长，到了现场常要重新挑选。我们希望他们出发前能根据公开说明选到合适的游戏。处理时只使用公开信息，不收集姓名等个人资料。这样可以减少等待，把更多时间留给游戏体验。</blockquote><p class="summary-paragraph">这段问题说明里有五项信息：</p><ol class="summary-list"><li class="summary-item"><span class="summary-index">01</span><span>对象：第一次参加的人。</span></li><li class="summary-item"><span class="summary-index">02</span><span>困难：不知道人数和时长，到场后重新等待。</span></li><li class="summary-item"><span class="summary-index">03</span><span>期望变化：出发前选到合适的游戏。</span></li><li class="summary-item"><span class="summary-index">04</span><span>边界：只用公开说明，不收集个人信息。</span></li><li class="summary-item"><span class="summary-index">05</span><span>处理价值：减少等待，增加游戏时间。</span></li></ol><aside class="summary-notice">注意，这里还没有决定一定要使用AI。</aside><p class="summary-paragraph">先把问题说清楚，后面才能判断该用什么方法，也才能判断AI是否适合参与。</p></div>
      </section>

      <section class="next-card" id="nextCard" aria-labelledby="nextTitle" hidden>
        <h2 id="nextTitle">下一课预告</h2>
        <p id="nextLessonPreview"></p>
      </section>

    </div>

    <div class="visual-lightbox" id="visualLightbox" hidden aria-hidden="true">
      <div class="visual-lightbox-dialog">
        <div class="visual-lightbox-stage"><img class="visual-lightbox-image" id="visualLightboxImage" alt=""></div>
        <button type="button" class="visual-lightbox-close" id="visualLightboxClose" aria-label="关闭大图"><span aria-hidden="true">×</span></button>
      </div>
    </div>

    <footer class="summary-footer">
      <button class="complete-button" id="completeButton" type="button">完成学习</button>
    </footer>
  </main>

  <script>
    /* ============================================================
       每课只允许替换 VISUAL_DATA 与本内容变量区中的完成头、原文内容及 pageAction。
       contentBlocks 必须按教案原顺序逐字录入，不得概括、删句、合并或去重。
       变量名、结构、HTML、CSS、渲染逻辑均不得修改。
       ============================================================ */
    const VISUAL_DATA = Object.freeze({"visualAsset":{"alt":"图片与文字分工小结","assetId":"L022-P07-C01","height":800,"imageType":"courseware_image","placement":{"anchorType":"page_type_rule","authority":"page_type_contract","decisionStatus":"final_fixed","fallback":"before_summary_body","insertAfter":"summary_title","insertBefore":"summary_body","inside":"summary_card","rule":"summary_card_image","terminalPlacementForbidden":true},"url":"https://res.xrunda.com/test/baseline/p07.webp","visualReview":{"fallbackUsed":false,"imageReviewed":false,"reviewNotRequiredReason":"fixed_page_type_placement"},"width":1200},"visualPresentation":{"borderRadiusPx":16,"groupLayout":"vertical_stack","heightPolicy":"natural_ratio","lightboxRequired":true,"objectFit":"contain","sizeRole":"primary_content_image","standaloneCard":false,"terminalPlacementForbidden":true,"thumbnailForbidden":true,"verticalSpacingPx":16,"widthPolicy":"content_width"}});

    function renderVisualAssets() {
      const gallery = document.getElementById("visualGallery");
      const lightbox = document.getElementById("visualLightbox");
      const lightboxImage = document.getElementById("visualLightboxImage");
      const closeButton = document.getElementById("visualLightboxClose");
      const stage = lightbox.querySelector(".visual-lightbox-stage");
      let scale = 1, translateX = 0, translateY = 0, startDistance = 0, startScale = 1, startX = 0, startY = 0;
      let bodyOverflow = "";
      function applyVisualTransform() { lightboxImage.style.transform = "translate(" + translateX + "px," + translateY + "px) scale(" + scale + ")"; }
      function resetVisualTransform() { scale = 1; translateX = 0; translateY = 0; applyVisualTransform(); }
      function touchDistance(touches) { const dx = touches[0].clientX - touches[1].clientX; const dy = touches[0].clientY - touches[1].clientY; return Math.sqrt(dx * dx + dy * dy); }
      function positionVisualClose() { const viewportHeight = window.innerHeight || document.documentElement.clientHeight; const imageRect = lightboxImage.getBoundingClientRect(); const lowerSpace = Math.max(0, viewportHeight - imageRect.bottom); closeButton.style.top = Math.round(imageRect.bottom + lowerSpace / 2 - 23) + "px"; }
      const assets = VISUAL_DATA.visualAsset ? [VISUAL_DATA.visualAsset] : (VISUAL_DATA.planVisualAssets || []);
      assets.forEach(function (asset) {
        const figure = document.createElement("figure");
        figure.className = "visual-figure";
        const trigger = document.createElement("button");
        trigger.type = "button";
        trigger.className = "image-zoom-trigger";
        trigger.setAttribute("aria-label", "放大查看配图");
        const image = document.createElement("img");
        image.className = "visual-image";
        image.src = asset.url;
        image.alt = asset.alt;
        trigger.appendChild(image);
        figure.appendChild(trigger);
        if (asset.displayLabel) {
          const caption = document.createElement("figcaption");
          caption.className = "visual-caption";
          caption.textContent = asset.displayLabel;
          figure.appendChild(caption);
        }
        trigger.addEventListener("click", function () {
          lightboxImage.src = asset.url;
          lightboxImage.alt = asset.alt;
          resetVisualTransform();
          bodyOverflow = document.body.style.overflow;
          document.body.style.overflow = "hidden";
          lightbox.hidden = false;
          lightbox.setAttribute("aria-hidden", "false");
          window.requestAnimationFrame(positionVisualClose);
        });
        gallery.appendChild(figure);
      });
      lightboxImage.onload = positionVisualClose;
      function closeVisualLightbox() {
        resetVisualTransform();
        lightbox.hidden = true;
        lightbox.setAttribute("aria-hidden", "true");
        document.body.style.overflow = bodyOverflow;
      }
      stage.addEventListener("touchstart", function (event) { if (event.touches.length === 2) { startDistance = touchDistance(event.touches); startScale = scale; event.preventDefault(); } else if (event.touches.length === 1 && scale > 1) { startX = event.touches[0].clientX - translateX; startY = event.touches[0].clientY - translateY; } }, { passive: false });
      stage.addEventListener("touchmove", function (event) { if (event.touches.length === 2 && startDistance > 0) { scale = Math.max(1, Math.min(4, startScale * touchDistance(event.touches) / startDistance)); if (scale <= 1) { translateX = 0; translateY = 0; } applyVisualTransform(); event.preventDefault(); } else if (event.touches.length === 1 && scale > 1) { translateX = event.touches[0].clientX - startX; translateY = event.touches[0].clientY - startY; applyVisualTransform(); event.preventDefault(); } }, { passive: false });
      stage.addEventListener("touchend", function () { startDistance = 0; if (scale <= 1) resetVisualTransform(); });
      closeButton.addEventListener("click", closeVisualLightbox);
      lightbox.addEventListener("click", function (event) {
        if (event.target === lightbox) closeVisualLightbox();
      });
      stage.addEventListener("click", function (event) { if (event.target === stage) closeVisualLightbox(); });
      document.addEventListener("keydown", function (event) {
        if (event.key === "Escape") closeVisualLightbox();
      });
      window.addEventListener("resize", function () { if (!lightbox.hidden) positionVisualClose(); });
    }
    document.addEventListener("DOMContentLoaded", renderVisualAssets);

    const COURSE_SUMMARY_VARIABLES = Object.freeze({"completionTitle":"恭喜你完成本节课程！","contentBlocks":[{"items":["图片呈现可见线索","文字补充画面外信息","放大查看不改变课程进度"],"type":"orderedList"}],"nextLessonPreview":"","pageAction":"complete","summaryTitle":"图片与文字各有分工"});
    /* ======================= 变量区结束 ======================= */

    function validateSummaryVariables(data) {
      const missing = [];
      const invalid = [];
      const allowedTypes = new Set(["paragraph", "orderedList", "blockquote", "notice", "codeBlock"]);

      if (typeof data.completionTitle !== "string" || !data.completionTitle.trim()) missing.push("completionTitle");
      if (typeof data.summaryTitle !== "string" || !data.summaryTitle.trim()) missing.push("summaryTitle");
      if (!Array.isArray(data.contentBlocks) || data.contentBlocks.length < 1) missing.push("contentBlocks");
      if (typeof data.nextLessonPreview !== "string") missing.push("nextLessonPreview");
      if (missing.length) throw new Error(`SUMMARY_FIELD_MISSING: ${missing.join(", ")}`);

      data.contentBlocks.forEach((block, blockIndex) => {
        if (!block || typeof block !== "object" || !allowedTypes.has(block.type)) {
          invalid.push(`contentBlocks[${blockIndex}].type`);
          return;
        }

        if (block.type === "orderedList") {
          if (!Array.isArray(block.items) || block.items.length < 1) {
            invalid.push(`contentBlocks[${blockIndex}].items`);
            return;
          }
          if (block.sourceNumbered !== undefined && typeof block.sourceNumbered !== "boolean") {
            invalid.push(`contentBlocks[${blockIndex}].sourceNumbered`);
          }
          block.items.forEach((item, itemIndex) => {
            if (typeof item !== "string" || !item.trim()) {
              invalid.push(`contentBlocks[${blockIndex}].items[${itemIndex}]`);
            }
          });
          return;
        }

        if (block.type === "codeBlock" && block.language !== undefined && typeof block.language !== "string") {
          invalid.push(`contentBlocks[${blockIndex}].language`);
        }

        if (typeof block.text !== "string" || !block.text.trim()) {
          invalid.push(`contentBlocks[${blockIndex}].text`);
        }
      });

      if (!new Set(["next", "complete"]).has(data.pageAction)) invalid.push("pageAction");
      if (invalid.length) throw new Error(`SUMMARY_FIELD_INVALID: ${invalid.join(", ")}`);
    }

    function safeNextPage() {
      if (
        window.CreatorReviewSDK &&
        (!window.CreatorReviewSDK.isAvailable || window.CreatorReviewSDK.isAvailable()) &&
        typeof window.CreatorReviewSDK.nextPage === "function"
      ) {
        window.CreatorReviewSDK.nextPage();
        return;
      }
      if (window.parent) window.parent.postMessage({ type: "nextpage" }, "*");
    }

    function safeComplete() {
      if (
        window.CreatorReviewSDK &&
        (!window.CreatorReviewSDK.isAvailable || window.CreatorReviewSDK.isAvailable()) &&
        typeof window.CreatorReviewSDK.complete === "function"
      ) {
        window.CreatorReviewSDK.complete();
        return;
      }
      if (window.parent) window.parent.postMessage({ type: "complete" }, "*");
    }

    function createTextBlock(tagName, className, text, blockType) {
      const element = document.createElement(tagName);
      element.className = className;
      element.dataset.blockType = blockType;
      element.textContent = text;
      return element;
    }

    function createOrderedListBlock(block) {
      const list = document.createElement("ol");
      list.className = "summary-list";
      list.dataset.blockType = "orderedList";
      list.dataset.numberingMode = block.sourceNumbered ? "source-plus-generated" : "generated";

      block.items.forEach((item, index) => {
        const listItem = document.createElement("li");
        listItem.className = "summary-item";

        const number = document.createElement("span");
        number.className = "summary-index";
        number.setAttribute("aria-hidden", "true");
        number.textContent = String(index + 1).padStart(2, "0");
        listItem.appendChild(number);

        const text = document.createElement("span");
        text.textContent = item;

        listItem.appendChild(text);
        list.appendChild(listItem);
      });

      return list;
    }

    function createCodeBlock(block) {
      const pre = document.createElement("pre");
      pre.className = "summary-code";
      pre.dataset.blockType = "codeBlock";
      if (block.language) pre.dataset.language = block.language;

      const code = document.createElement("code");
      code.textContent = block.text;
      pre.appendChild(code);
      return pre;
    }

    function renderContentBlocks(container, blocks) {
      const fragment = document.createDocumentFragment();

      blocks.forEach(block => {
        if (block.type === "orderedList") {
          fragment.appendChild(createOrderedListBlock(block));
          return;
        }

        if (block.type === "codeBlock") {
          fragment.appendChild(createCodeBlock(block));
          return;
        }

        const blockConfig = {
          paragraph: ["p", "summary-paragraph"],
          blockquote: ["blockquote", "summary-quote"],
          notice: ["aside", "summary-notice"]
        }[block.type];

        fragment.appendChild(createTextBlock(blockConfig[0], blockConfig[1], block.text, block.type));
      });

      container.textContent = "";
      container.appendChild(fragment);
    }

    function configurePageAction(button, pageAction) {
      if (pageAction === "next") {
        button.textContent = "继续学习";
        button.addEventListener("click", safeNextPage);
        return;
      }

      button.textContent = "完成学习";
      button.addEventListener("click", safeComplete);
    }

    function renderSummaryPage() {
      const data = COURSE_SUMMARY_VARIABLES;
      validateSummaryVariables(data);

      document.getElementById("completionTitle").textContent = data.completionTitle;
      document.getElementById("summaryTitle").textContent = data.summaryTitle;
      renderContentBlocks(document.getElementById("summaryContent"), data.contentBlocks);
      const summaryCard = document.querySelector(".summary-card");
      summaryCard.classList.toggle("summary-card--single-block", data.contentBlocks.length === 1);

      const nextCard = document.getElementById("nextCard");
      if (data.nextLessonPreview.trim()) {
        document.getElementById("nextLessonPreview").textContent = data.nextLessonPreview;
        nextCard.hidden = false;
      }

      const button = document.getElementById("completeButton");
      configurePageAction(button, data.pageAction);
    }

    function syncLayoutMetrics() {
      const footer = document.querySelector(".summary-footer");
      const height = Math.ceil(footer.getBoundingClientRect().height || 80);
      document.documentElement.style.setProperty("--footer-h", `${height}px`);
    }

    try {
      renderSummaryPage();
      syncLayoutMetrics();
      if ("ResizeObserver" in window) {
        new ResizeObserver(syncLayoutMetrics).observe(document.querySelector(".summary-footer"));
      }
      window.addEventListener("resize", syncLayoutMetrics, { passive: true });
      window.addEventListener("orientationchange", () => setTimeout(syncLayoutMetrics, 120), { passive: true });
    } catch (error) {
      document.documentElement.dataset.summaryError = "SUMMARY_FIELD_MISSING";
      document.body.innerHTML = '<main class="summary-error" role="alert">课程小结内容暂不可用</main>';
      throw error;
    }
  </script>
</body>
</html>
